def count_triples(N, K):
    dp = [defaultdict(int) for _ in range(3)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        new_dp = [defaultdict(int) for _ in range(3)]
        for j in range(K):
            for k in range(K):
                if (j + k) % K == 0:
                    new_dp[0][(i * j) % K] += dp[2][k]
                if (k + j) % K == 0:
                    new_dp[1][(i * k) % K] += dp[0][j]
                if (j + k) % K == 0:
                    new_dp[2][(i * j) % K] += dp[1][k]
        dp = new_dp

    return sum(dp[i][0] for i in range(3))

